<?php
require_once __DIR__.'/config/app.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: my-reports.php');exit();}$uid=(int)$_SESSION['user_id'];$id=(int)($_POST['id']??0);$s=mysqli_prepare($conn,'SELECT image,status FROM items WHERE id=? AND user_id=?');mysqli_stmt_bind_param($s,'ii',$id,$uid);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(mysqli_num_rows($r)!==1){set_flash('error','Report not found.');header('Location: my-reports.php');exit();}$item=mysqli_fetch_assoc($r);if($item['status']!=='active'){set_flash('error','Returned items cannot be deleted.');header('Location: my-reports.php');exit();}$c=mysqli_prepare($conn,"SELECT COUNT(*) total FROM claims WHERE item_id=? AND status='pending'");mysqli_stmt_bind_param($c,'i',$id);mysqli_stmt_execute($c);if((int)mysqli_fetch_assoc(mysqli_stmt_get_result($c))['total']>0){set_flash('error','This report has a pending claim and cannot be deleted.');header('Location: my-reports.php');exit();}$d=mysqli_prepare($conn,'DELETE FROM items WHERE id=? AND user_id=?');mysqli_stmt_bind_param($d,'ii',$id,$uid);if(mysqli_stmt_execute($d)){delete_item_image($item['image'],__DIR__.'/uploads');set_flash('success','Report deleted.');}else set_flash('error','Could not delete the report.');header('Location: my-reports.php');exit();
?>